from datetime import date,timedelta
holidays={date.fromisoformat(x) for x in ['2026-11-20','2026-12-08','2026-12-24','2026-12-25','2026-12-31','2027-01-01']}
susp=lambda d:date(2026,12,20)<=d<=date(2027,1,20)
def reason(d):
 if susp(d):return 'suspensão art. 220'
 if d in holidays:return 'feriado/sem expediente'
 if d.weekday()>=5:return 'fim de semana'
 return 'útil'
for name,start,end in [('citacao',date(2026,11,19),date(2026,12,15)),('sentenca',date(2026,12,10),date(2027,2,3))]:
 print(name)
 n=0;d=start
 while d<=end:
  if name=='citacao': count=d>=date(2026,11,24)
  else: count=d>=date(2026,12,14)
  if count and reason(d)=='útil':n+=1
  print(d,d.strftime('%a'),reason(d),n if count and reason(d)=='útil' else '-')
  d+=timedelta(days=1)
PY"

